# shellcheck shell=bash
# Source me: `source ./env.sh`
# Exports the connection settings for demo-app/rag.py, reading the
# application password generated by CloudNativePG.
_ns=llm
_pw="$(kubectl get secret vectordb-app -n "${_ns}" -o jsonpath='{.data.password}' | base64 -d)"
export DATABASE_URL="postgresql://raguser:${_pw}@localhost:${PG_LOCAL_PORT:-15432}/ragdb"
export EMBED_URL="${EMBED_URL:-http://localhost:11434}"
export EMBED_MODEL="${EMBED_MODEL:-nomic-embed-text}"
export LLM_URL="${LLM_URL:-http://localhost:11434}"
unset _ns _pw
echo "DATABASE_URL=postgresql://raguser:***@localhost:${PG_LOCAL_PORT:-15432}/ragdb"
echo "EMBED_URL=${EMBED_URL} (${EMBED_MODEL})"
echo "LLM_URL=${LLM_URL}${LLM_MODEL:+ (${LLM_MODEL})}"
